new='''/**
 * Moves an issue into another project (ADR 0011), atomically: the issue takes
 * the target project's next number, its old number is retired in the source
 * project, and its search document follows it. Nothing else on the row — or
 * on the rows that reference it — changes.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<{ issue: Issue; fromProjectId: ProjectId; fromNumber: number }> {
  const moved = getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) throw new Error(`Issue ${issueId} not found`);

    const fromProjectId = current.projectId as ProjectId;
    const fromNumber = current.number;

    // Retire every number the source project has issued so far, the moved
    // issue's included, before the row stops vouching for it.
    rememberIssuedNumber(
      tx,
      orgId,
      fromProjectId,
      Math.max(fromNumber, highestIssuedNumber(tx, orgId, fromProjectId)),
    );

    const toNumber = highestIssuedNumber(tx, orgId, toProjectId) + 1;
    rememberIssuedNumber(tx, orgId, toProjectId, toNumber);

    tx.update(issues)
      .set({
        projectId: toProjectId,
        number: toNumber,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .run();

    tx.update(searchIndex)
      .set({ projectId: toProjectId })
      .where(
        and(
          orgPredicate(searchIndex.orgId, orgId),
          eq(searchIndex.subjectKind, "issue"),
          eq(searchIndex.subjectId, issueId),
        ),
      )
      .run();

    return { fromProjectId, fromNumber };
  });

  const issue = await findIssueById(orgId, issueId);
  if (!issue) throw new Error(`Issue ${issueId} not found`);
  return { issue, ...moved };
}

