      Math.max(fromNumber, highestIssuedNumber(tx, orgId, fromProjectId)),
    );

    const toNumber = highestIssuedNumber(tx, orgId, toProjectId) + 1;
    rememberIssuedNumber(tx, orgId, toProjectId, toNumber);

    tx.update(issues)
      .set({
        projectId: toProjectId,
        number: toNumber,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .run();

    tx.update(searchIndex)
      .set({ projectId: toProjectId })
      .where(
        and(
          orgPredicate(searchIndex.orgId, orgId),
          eq(searchIndex.subjectKind, "issue"),
          eq(searchIndex.subjectId, issueId),
        ),
      )
      .run();

    return { fromProjectId, fromNumber };
  });

  const issue = await findIssueById(orgId, issueId);
  if (!issue) throw new Error(`Issue ${issueId} not found`);
  return { issue, ...moved };
}

