import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import * as issueService from "@/server/services/issue-service";
import * as projectRepo from "@/server/repositories/project-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import { registerSearchListeners } from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("moves", async () => {
  const t = await createTenant("mv");
  registerActivityListeners(); registerSearchListeners();
  const p2 = await projectRepo.insertProject({ orgId: t.org.id, name: "two", slug: "two", key: "TWO", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null } as never);
  const a = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "alpha one" }));
  const b = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "beta two" }));
  const seen: unknown[] = [];
  for (const k of ["issue.moved", "issue.updated", "issue.created", "issue.archived"] as const) subscribe(k, (p) => { seen.push([k, p]); });
  const moved = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: b.id, toProjectId: p2.id });
  expect(moved).toMatchObject({ projectId: p2.id, number: 1, title: "beta two" });
  const back = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: b.id, toProjectId: t.project.id });
  expect(back.number).toBe(3);
  const c = await issueService.createIssue(t.actors.member, issueInput(t.org.id, p2.id));
  expect(c.number).toBe(2);
  const same = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: a.id, toProjectId: t.project.id });
  expect(same.number).toBe(1);
  expect(seen).toHaveLength(2);
  await expect(issueService.moveIssueToProject(t.actors.viewer, { orgId: t.org.id, issueId: a.id, toProjectId: p2.id })).rejects.toThrow();
  const acts = await activityRepo.listActivity({ orgId: t.org.id, action: ["issue.moved"], limit: 50, cursor: null });
  expect(acts.items).toHaveLength(2);
  console.log(acts.items[1]);
  const hits = await searchRepo.searchDocuments({ orgId: t.org.id, q: "beta", kinds: [], projectId: p2.id, limit: 10, cursor: null } as never);
  expect(hits.items).toHaveLength(0);
});
EOF
